-- One-time legacy campaign import for Arta Malanda.
-- Source: old Supabase CSV export rows.zip.
-- Safe intent: import campaign context while keeping old player characters unclaimed.
-- Run after supabase/RUN_THIS_IN_SUPABASE.sql has completed successfully.

begin;

alter table public.characters add column if not exists legacy_owner_name text not null default '';

create table if not exists public.legacy_profiles (
  id uuid primary key,
  display_name text not null,
  role text not null default 'player',
  imported_at timestamptz not null default now()
);

create table if not exists public.legacy_loot_generator_config (
  id text primary key,
  biomes jsonb not null default '[]'::jsonb,
  difficulties jsonb not null default '[]'::jsonb,
  pool_sizes jsonb not null default '[]'::jsonb,
  room_types jsonb not null default '[]'::jsonb,
  room_rules jsonb not null default '{}'::jsonb,
  rare_rules jsonb not null default '{}'::jsonb,
  formula_notes jsonb not null default '{}'::jsonb,
  source_updated_at timestamptz,
  imported_at timestamptz not null default now()
);

on conflict (id) do update set display_name = excluded.display_name, role = excluded.role;

on conflict (class_key) do update set name = excluded.name, role = excluded.role, armor = excluded.armor, identity = excluded.identity, base_hp = excluded.base_hp, base_mana = excluded.base_mana, inventory_slots = excluded.inventory_slots, spell_slots = excluded.spell_slots, attributes = excluded.attributes, passives = excluded.passives, token_color = excluded.token_color;

on conflict (city_key) do update set name = excluded.name, is_locked = excluded.is_locked, display_order = excluded.display_order;

on conflict (vendor_key) do update set city_key = excluded.city_key, name = excluded.name, facility = excluded.facility, category = excluded.category, is_hidden = excluded.is_hidden, display_order = excluded.display_order;

on conflict (product_key) do update set vendor_id = excluded.vendor_id, item_name = excluded.item_name, description = excluded.description, item_type = excluded.item_type, rarity = excluded.rarity, price_coin = excluded.price_coin, stock_quantity = excluded.stock_quantity, is_available = excluded.is_available, display_order = excluded.display_order;

on conflict (spell_key) do update set name = excluded.name, school = excluded.school, mana_cost = excluded.mana_cost, summary = excluded.summary, details = excluded.details, is_available = excluded.is_available, display_order = excluded.display_order;

