insert into public.class_templates (id, class_key, name, role, armor, identity, base_hp, base_mana, inventory_slots, spell_slots, attributes, passives, token_color) values
('12c2ee5c-6e3f-4964-9420-6787ea5216ec'::uuid, 'sage', 'Sage', 'Support · Poor sustain', 'Medium armor', 'Selfless support casters whose mastery of recovery turns a single act of healing into aid for the whole party.', 70, 100, 12, 5, '{"range":0,"agility":2,"alchemy":0,"stealth":0,"accuracy":-2,"charisma":2,"recovery":3,"strength":-2,"vitality":-2,"mana_regen":2,"perception":0,"intelligence":-5}'::jsonb, '["Healing and enhancement spells use Recovery instead of Intelligence for magic rolls.","Heals also restore half the amount, rounded up, to another ally or the original target."]'::jsonb, '#8a6da1'),
('255bd154-6448-4618-9db5-ee5fc6dd3773'::uuid, 'rogue', 'Rogue', 'Attack · Poor sustain', 'Light armor', 'Cunning duelists who thrive on surprise, isolation, and catching enemies at their most vulnerable.', 90, 50, 16, 3, '{"range":0,"agility":2,"alchemy":1,"stealth":3,"accuracy":0,"charisma":-3,"recovery":0,"strength":-1,"vitality":-1,"mana_regen":0,"perception":3,"intelligence":0}'::jsonb, '["Backstab deals double damage from behind, from stealth, or against a pinned or defenseless target.","May use Agility instead of Strength for attacks that trigger Backstab."]'::jsonb, '#9a6e52'),
('25c38093-7a99-438e-af16-14a6798663d5'::uuid, 'apprentice', 'Apprentice', 'Hybrid · Decent sustain', 'Medium armor', 'Naturally talented learners who trade some magical utility for freedom, adaptability, and staying power.', 100, 75, 16, 5, '{"range":0,"agility":1,"alchemy":1,"stealth":0,"accuracy":0,"charisma":0,"recovery":0,"strength":0,"vitality":-1,"mana_regen":1,"perception":0,"intelligence":1}'::jsonb, '["While paired with a Mage: +1 Intelligence.","While paired with a Knight: +1 Strength.","While paired with a Ranger: +1 Accuracy. These bonuses can stack."]'::jsonb, '#9a6e52'),
('35443c8a-52c3-4626-964f-de8ce5c7f2c5'::uuid, 'apothecary', 'Apothecary', 'Support · Great sustain', 'Medium armor', 'Durable battlefield mages whose restorative support can hold a party together even on the front line.', 130, 90, 15, 5, '{"range":0,"agility":-1,"alchemy":2,"stealth":-2,"accuracy":-1,"charisma":0,"recovery":2,"strength":-3,"vitality":1,"mana_regen":2,"perception":0,"intelligence":0}'::jsonb, '["Can heal an ally for 10 HP in place of movement."]'::jsonb, '#5579a8'),
('564c9d0c-1dd5-499e-a157-454ca7733663'::uuid, 'mendrunner', 'Mendrunner', 'Hybrid · Poor sustain', 'Medium armor', 'Nimble practitioners of botany and natural medicine who reject magic in favor of hard-won remedies.', 85, 0, 20, 0, '{"range":0,"agility":3,"alchemy":4,"stealth":1,"accuracy":1,"charisma":-3,"recovery":3,"strength":-1,"vitality":0,"mana_regen":0,"perception":3,"intelligence":-5}'::jsonb, '["Heal an ally for 2d6 + Recovery + Alchemy and remove one debuff or negative effect; 1-turn cooldown.","Immune to poison and illness."]'::jsonb, '#4d8f83'),
('5783bad6-bee3-44c6-935e-24be35adf0c6'::uuid, 'talismanist', 'Talismanist', 'Attack · Decent sustain', 'Medium armor', 'Rune-armed warriors who bind magic into weapons and armor, turning every piece of gear into a spell vessel.', 125, 100, 10, 0, '{"range":0,"agility":0,"alchemy":-1,"stealth":-2,"accuracy":1,"charisma":0,"recovery":0,"strength":1,"vitality":1,"mana_regen":0,"perception":0,"intelligence":1}'::jsonb, '["Begins with three random low-level runes.","Requires only three runes to force a spell into a weapon instead of five; additional runes improve the result.","Each spell-infused weapon on hand can cast its spell twice per combat."]'::jsonb, '#a05e5a'),
('71a33c37-97c5-4ed0-99d5-13ce1baf5ddf'::uuid, 'knight', 'Knight', 'Attack · Decent sustain', 'Medium armor', 'Well-rounded combat experts with political presence, battlefield leadership, and a talent for mounted fighting.', 125, 25, 14, 2, '{"range":-1,"agility":0,"alchemy":-1,"stealth":0,"accuracy":1,"charisma":2,"recovery":0,"strength":1,"vitality":1,"mana_regen":-2,"perception":0,"intelligence":-1}'::jsonb, '["+1 Strength while mounted on a horse.","When hit, a parry roll of 18–20 prevents all damage; 15–17 prevents half, rounded up.","Once per combat, Rally the Troops lets the party attack one target together; if the Knight hits, the others do as well."]'::jsonb, '#b28b45'),
('89044c92-2bbf-4bc3-a87f-e9b4a8d3d46e'::uuid, 'armor-clad', 'Armor-clad', 'Defense · Great sustain', 'Heavy armor', 'Relentless front-line warriors who sacrifice speed and subtlety for overwhelming defensive presence.', 165, 50, 10, 1, '{"range":-2,"agility":-3,"alchemy":1,"stealth":-2,"accuracy":0,"charisma":-1,"recovery":0,"strength":2,"vitality":3,"mana_regen":0,"perception":-1,"intelligence":-3}'::jsonb, '["Distribution redirects 50% of a target’s incoming damage to the Armor-clad.","Pays only material costs for armor labor.","Cannot receive additional defensive bonuses from shields."]'::jsonb, '#8a6da1'),
('9cf9d255-e4cc-4cb6-996f-335e9e3eb7ed'::uuid, 'blacksmith', 'Blacksmith', 'Support · Decent sustain', 'Medium armor', 'Practical craftspeople whose command of tools, weapons, armor, and runes makes them invaluable anywhere.', 125, 50, 18, 3, '{"range":-2,"agility":-1,"alchemy":1,"stealth":-1,"accuracy":0,"charisma":2,"recovery":0,"strength":2,"vitality":1,"mana_regen":0,"perception":0,"intelligence":0}'::jsonb, '["Pays only material costs for smithing labor.","Can create weapons away from a forge with a properly made fire.","Once per combat, grant a chosen melee weapon +1 Strength until combat or the scene ends."]'::jsonb, '#77875a'),
('ae6059b2-ec83-4393-b5a3-920d43817f92'::uuid, 'beastmaster', 'Beastmaster', 'Hybrid · Poor sustain', 'Light armor', 'Rare animal handlers whose companions become a force of their own across the battlefield.', 90, 50, 20, 1, '{"range":0,"agility":1,"alchemy":0,"stealth":0,"accuracy":1,"charisma":3,"recovery":1,"strength":-3,"vitality":0,"mana_regen":0,"perception":2,"intelligence":0}'::jsonb, '["Tame is a free spell and uses d6 + Charisma + buffs against a creature’s Wild score; wounded creatures are easier to tame.","Attacks against animals and beasts cannot reduce them below 1 HP and always critically hit.","May bring up to 20 Wild score worth of beasts per mission; each receives its own initiative and turn."]'::jsonb, '#a05e5a'),
('c48108ef-e331-4d38-89bd-5aa2162175b5'::uuid, 'ranger', 'Ranger', 'Attack · Poor sustain', 'Light armor', 'Back-line attackers and scouts who combine punishing range with reconnaissance and specialized ammunition.', 90, 50, 15, 1, '{"range":3,"agility":1,"alchemy":0,"stealth":1,"accuracy":2,"charisma":0,"recovery":0,"strength":-2,"vitality":-2,"mana_regen":0,"perception":2,"intelligence":1}'::jsonb, '["Can tame birds.","Three times per combat, fire three arrows in one draw; roll accuracy for each arrow.","May buy and craft elemental or effect-tipped arrows."]'::jsonb, '#5579a8'),
('c6baa808-d48c-4cd6-b92b-b84fd650e167'::uuid, 'alchemist', 'Alchemist', 'Support · Decent sustain', 'Light armor', 'Intelligent and resourceful seekers of knowledge, renowned for their command of potions and alchemical craft.', 110, 50, 16, 2, '{"range":0,"agility":0,"alchemy":5,"stealth":0,"accuracy":0,"charisma":0,"recovery":1,"strength":-1,"vitality":-1,"mana_regen":0,"perception":0,"intelligence":1}'::jsonb, '["Once per combat, use or make a potion or alchemical item without spending the main action or movement.","Has unlimited flasks and Arcane Nectar while maintaining a house or residence."]'::jsonb, '#4d8f83'),
('e0b11d81-0052-4e06-9451-a78fc39132a1'::uuid, 'mage', 'Mage', 'Attack · Poor sustain', 'Light armor', 'Versatile magical heavy-hitters with an answer for nearly every problem—provided they survive long enough to cast it.', 70, 100, 10, 10, '{"range":1,"agility":0,"alchemy":0,"stealth":0,"accuracy":0,"charisma":1,"recovery":0,"strength":-3,"vitality":-3,"mana_regen":1,"perception":0,"intelligence":3}'::jsonb, '["Regain 10 Mana whenever an enemy is killed with a spell."]'::jsonb, '#567a7f'),
('f6d35493-6016-4ccd-95b5-13fc72d386b6'::uuid, 'the-muscle', 'The Muscle', 'Defense · Great sustain', 'Medium armor', 'Notorious for a large frame and small brains, built to soak punishment and become the group’s blunt-force answer.', 150, 40, 10, 1, '{"range":-2,"agility":-1,"alchemy":-2,"stealth":-2,"accuracy":-2,"charisma":-2,"recovery":2,"strength":3,"vitality":1,"mana_regen":0,"perception":-1,"intelligence":-3}'::jsonb, '["When The Muscle kills an enemy, gain 1d6 for ensuing damage rolls. Resets after each combat or scene ends. Max of 5d6."]'::jsonb, '#a96342'),
('fb137c8b-ea82-4162-af56-d266228102f0'::uuid, 'warden', 'Warden', 'Hybrid · Decent sustain', 'Medium armor', 'Jack-of-all-trades survivalists with broad usefulness, cunning instincts, and flexible party support.', 110, 75, 20, 3, '{"range":0,"agility":0,"alchemy":1,"stealth":0,"accuracy":0,"charisma":-2,"recovery":0,"strength":0,"vitality":0,"mana_regen":0,"perception":2,"intelligence":0}'::jsonb, '["Once per combat or exploration scene, reroll a failed Perception, Alchemy, Survival, or Utility check.","Gains a +2 modifier of choice in a single category where the party has no bonuses."]'::jsonb, '#5d8067')
